import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    edges = []
    idx = 2
    for i in range(m):
        u = int(data[idx])
        v = int(data[idx+1])
        w = int(data[idx+2])
        edges.append((w, u, v))
        idx += 3

    edges.sort()

    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_cost = 0

    for w, u, v in edges:
        if union(u, v):
            mst_edges.append((u, v, w))
            total_cost += w

    for u, v, w in mst_edges:
        print(f"{u} - {v} : {w}")

    print(f"Total Cost: {total_cost}")

if __name__ == "__main__":
    main()
